ST.xhtml:p:
LevelTrigger(CLK := g_biTailCylinderLevel);
SlopeTrigger(CLK := g_biTailCylinderSlope);
R_Trigger(CLK := g_biTailCylinderClose);

IF LevelTrigger.Q THEN
  g_boTailCylinderSlope := FALSE;
  g_boTailCylinderDone := FALSE;
  nTailState := 1;
END_IF;
IF SlopeTrigger.Q THEN
  g_boTailCylinderSlope := TRUE;
  g_boTailCylinderDone := FALSE;
  nTailState := 1;
END_IF;
IF R_Trigger.Q THEN
  g_boTailCylinderDone := FALSE;
END_IF;

CASE nTailState OF
  0:
    nTailState := 0;
  1:
    DelayInPlace(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nCylinderDelay)));
    IF DelayInPlace.Q THEN
      g_boTailCylinderDone := TRUE;
      DelayInPlace(IN := FALSE);
      nTailState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  g_boTailCylinderSlope := FALSE;
  nTailState := 0;
  DelayInPlace(IN := FALSE);
END_IF;
